ALTER TABLE market_account ADD COLUMN row_version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE market_account ADD COLUMN deleted_at INTEGER;
ALTER TABLE market_account ADD COLUMN last_operation TEXT;
ALTER TABLE market_public_release ADD COLUMN row_version INTEGER NOT NULL DEFAULT 1;
ALTER TABLE market_public_release ADD COLUMN removal_reason TEXT;
ALTER TABLE market_public_release ADD COLUMN removed_at INTEGER;
ALTER TABLE market_public_release ADD COLUMN last_operation TEXT;
CREATE TABLE market_report (id TEXT PRIMARY KEY, pack_id TEXT NOT NULL, release_id TEXT NOT NULL, receipt_hash TEXT NOT NULL UNIQUE, reason TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','resolved')), resolution TEXT, row_version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, last_operation TEXT);
CREATE TABLE market_lifecycle_operation (actor TEXT NOT NULL, route TEXT NOT NULL, operation TEXT NOT NULL, request_hash TEXT NOT NULL, status INTEGER NOT NULL, result TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(actor,route,operation));
CREATE TABLE market_lifecycle_audit (id TEXT PRIMARY KEY, actor TEXT NOT NULL, entity TEXT NOT NULL, previous_state TEXT NOT NULL, next_state TEXT NOT NULL, reason TEXT NOT NULL, request_id TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE market_revocation (seq INTEGER PRIMARY KEY AUTOINCREMENT, pack_id TEXT NOT NULL, release_id TEXT NOT NULL, archive_sha256 TEXT NOT NULL, state TEXT NOT NULL, reason_code TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(release_id,state));
CREATE TABLE market_retention_clock (id TEXT PRIMARY KEY CHECK(id='cleanup'), audit_before INTEGER NOT NULL DEFAULT 0);
CREATE TRIGGER market_last_admin BEFORE UPDATE OF role,disabled,deleted_at ON market_account WHEN OLD.role='admin' AND OLD.disabled=0 AND (NEW.role!='admin' OR NEW.disabled!=0 OR NEW.deleted_at IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM market_account WHERE id!=OLD.id AND role='admin' AND disabled=0 AND deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'LAST_ADMIN'); END;
CREATE TRIGGER market_safety_sticky BEFORE UPDATE OF state ON market_public_release WHEN OLD.state='safety_removed' AND NEW.state!='safety_removed' BEGIN SELECT RAISE(ABORT,'SAFETY_STICKY'); END;
CREATE TRIGGER market_lifecycle_audit_immutable BEFORE UPDATE ON market_lifecycle_audit BEGIN SELECT RAISE(ABORT,'AUDIT_APPEND_ONLY'); END;
CREATE TRIGGER market_lifecycle_audit_retention BEFORE DELETE ON market_lifecycle_audit WHEN OLD.created_at >= COALESCE((SELECT audit_before FROM market_retention_clock WHERE id='cleanup'),0) BEGIN SELECT RAISE(ABORT,'AUDIT_RETENTION'); END;
CREATE INDEX market_report_queue ON market_report(state,created_at,id);
CREATE INDEX market_revocation_time ON market_revocation(created_at,seq);
DROP TRIGGER market_review_audit_no_delete;
CREATE TRIGGER market_review_audit_retention BEFORE DELETE ON market_review_audit WHEN OLD.created_at >= COALESCE((SELECT audit_before FROM market_retention_clock WHERE id='cleanup'),0) OR EXISTS(SELECT 1 FROM market_public_release WHERE release_id=OLD.release_id AND state='published') BEGIN SELECT RAISE(ABORT,'AUDIT_RETENTION'); END;
